            if board[r][i] == v or board[i][c] == v: return False
        br, bc = 3*(r//3), 3*(c//3)
        for i in range(br, br+3):
            for j in range(bc, bc+3):
                if board[i][j] == v: return False
        return True
    def bt():
        spot = find()
